    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "曾以为伸手 就能够到天边"
        },
        {
          "id": "C1-02",
          "zh": "那时的我如今 又站在哪里"
        },
        {
          "id": "C1-03",
          "zh": "也许 变得成熟 变得沉默"
        },
        {
          "id": "C1-04",
          "zh": "其实 不是那样的答案"
        },
        {
          "id": "C1-05",
          "zh": "只差一点点 就能推开的门"
        },
        {
          "id": "C1-06",
          "zh": "能改变的明天 确实存在过"
        },
        {
          "id": "C1-07",
          "zh": "偏偏我 连这都没能看清"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "C1-01",
          "zh": "曾以为能去往任何地方"
        },
        {
          "id": "C1-02",
          "zh": "那时的我如今在何方"
        },
        {
          "id": "C1-03",
          "zh": "也许 是长成了大人"
        },
        {
          "id": "C1-04",
          "zh": "可 并不是那样的事啊"
        },
        {
          "id": "C1-05",
          "zh": "再多一点点的勇气"
        },
        {
          "id": "C1-06",
          "zh": "就能改变 曾有过的明天"
        },
        {
          "id": "C1-07",
          "zh": "连这 都没能察觉啊"
        }
      ]
    }
  ]
}

